<template><p v-if="loading" role="status">正在載入私人記錄…</p><div v-if="error" class="canonical-alert" role="alert">{{ error }} <a v-if="authRequired" href="/signin-with-chatgpt?return_to=/?workspace=observations" target="_top">登入 ChatGPT</a><button type="button" @click="$emit('reload')">{{ reloadLabel||'重新載入私人記錄' }}</button></div><p v-if="message" role="status" class="save-message">{{ message }}</p><p v-if="loaded && storage==='isolated_local_qa'" class="storage-label">{{ storage==='isolated_local_qa'?'本機隔離測試資料':'正式私人記錄 · 目前登入身份' }}</p></template>
<script setup>defineProps({loading:Boolean,error:String,authRequired:Boolean,message:String,loaded:Boolean,storage:String,reloadLabel:String});defineEmits(['reload']);</script>
